// Generates drizzle/0001_sync.sql from the table registry: change capture, append-only guards, and the
// trigger-maintained caches. Run by `npm run db:generate`. Do not edit the output by hand.
import { writeFileSync } from 'node:fs';
import { REGISTRY } from '../src/schema/helpers';
import '../src/schema/index';

const out: string[] = [];
const add = (s: string) => out.push(s.trim());

add(`-- GENERATED by scripts/gen-sql.ts from the table registry. Do not edit.
-- tillbox.suppress = 'on'  : a device is applying remote changes (do not echo them back)
-- tillbox.origin   = <id>  : the server is applying changes pushed by this device`);
add(`CREATE FUNCTION tb_capture() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE o text;
BEGIN
  IF current_setting('tillbox.suppress', true) = 'on' THEN RETURN NULL; END IF;
  o := coalesce(nullif(current_setting('tillbox.origin', true), ''), (SELECT value FROM meta WHERE key = 'device_id'));
  INSERT INTO outbox (table_name, row_id, op, payload, origin) VALUES (TG_TABLE_NAME, NEW.id, TG_OP, to_jsonb(NEW), o);
  RETURN NULL;
END $$;`);
add(`CREATE FUNCTION tb_no_update_delete() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'table % is append-only', TG_TABLE_NAME; END $$;`);
add(`CREATE FUNCTION tb_no_delete() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'rows in % are archived, never deleted', TG_TABLE_NAME; END $$;`);

const names = [...REGISTRY.keys()].sort();
for (const name of names) {
  const { cls } = REGISTRY.get(name)!;
  if (cls === 'local') continue;
  if (cls === 'ledger') {
    add(`CREATE TRIGGER tb_capture_${name} AFTER INSERT ON ${name} FOR EACH ROW EXECUTE FUNCTION tb_capture();`);
    add(`CREATE TRIGGER tb_guard_${name} BEFORE UPDATE OR DELETE ON ${name} FOR EACH ROW EXECUTE FUNCTION tb_no_update_delete();`);
  } else {
    add(`CREATE TRIGGER tb_capture_${name} AFTER INSERT OR UPDATE ON ${name} FOR EACH ROW EXECUTE FUNCTION tb_capture();`);
    add(`CREATE TRIGGER tb_guard_${name} BEFORE DELETE ON ${name} FOR EACH ROW EXECUTE FUNCTION tb_no_delete();`);
  }
}

add(`-- Stock level cache: SUM(qty) per product unit. Fires for local writes AND for rows applied from sync.
CREATE FUNCTION tb_stock_level() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO stock_levels (product_unit_id, qty) VALUES (NEW.product_unit_id, NEW.qty)
  ON CONFLICT (product_unit_id) DO UPDATE SET qty = stock_levels.qty + EXCLUDED.qty;
  RETURN NULL;
END $$;`);
add(`CREATE TRIGGER tb_stock_level AFTER INSERT ON stock_movements FOR EACH ROW EXECUTE FUNCTION tb_stock_level();`);

add(`-- Current order status = the latest event of each field. Recomputed from the events, so out-of-order arrival is safe.
CREATE FUNCTION tb_order_state() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE latest text;
BEGIN
  SELECT value INTO latest FROM order_status_events WHERE order_id = NEW.order_id AND field = NEW.field ORDER BY created_at DESC, id DESC LIMIT 1;
  INSERT INTO order_state (order_id) VALUES (NEW.order_id) ON CONFLICT (order_id) DO NOTHING;
  IF NEW.field = 'payment' THEN UPDATE order_state SET payment_status = latest, updated_at = now() WHERE order_id = NEW.order_id;
  ELSIF NEW.field = 'process' THEN UPDATE order_state SET process_status = latest, updated_at = now() WHERE order_id = NEW.order_id;
  ELSE UPDATE order_state SET delivery_status = latest, updated_at = now() WHERE order_id = NEW.order_id;
  END IF;
  RETURN NULL;
END $$;`);
add(`CREATE TRIGGER tb_order_state AFTER INSERT ON order_status_events FOR EACH ROW EXECUTE FUNCTION tb_order_state();`);

add(`-- A journal entry written on this device must balance at commit. Entries arriving from sync are not re-checked,
-- because a batch can end between two lines of one entry.
CREATE FUNCTION tb_journal_balanced() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE d bigint; c bigint;
BEGIN
  IF current_setting('tillbox.suppress', true) = 'on' OR coalesce(current_setting('tillbox.origin', true), '') <> '' THEN RETURN NULL; END IF;
  SELECT coalesce(sum(debit_cents), 0), coalesce(sum(credit_cents), 0) INTO d, c FROM journal_lines WHERE entry_id = NEW.entry_id;
  IF d <> c THEN RAISE EXCEPTION 'journal entry % does not balance (debit %, credit %)', NEW.entry_id, d, c; END IF;
  RETURN NULL;
END $$;`);
add(`CREATE CONSTRAINT TRIGGER tb_journal_balanced AFTER INSERT ON journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION tb_journal_balanced();`);

writeFileSync('drizzle/0001_sync.sql', out.join('\n--> statement-breakpoint\n') + '\n');
console.log(`sync SQL: ${names.filter((n) => REGISTRY.get(n)!.cls !== 'local').length} synced tables, ${names.filter((n) => REGISTRY.get(n)!.cls === 'local').length} local`);
